#!/usr/bin/env python3
"""Every entry of the two baseline POSITIONS.md versions must be verbatim in
exactly one of POSITIONS.md and POSITIONS-history.md at the worktree's state.
An entry is a top-level bullet ("- " at column 0) with its indented lines."""
import subprocess, sys, collections

REPO = sys.argv[1] if len(sys.argv) > 1 else "/home/user/fortress-audit"
REV = sys.argv[2] if len(sys.argv) > 2 else None   # None: the working tree
P = "explorations/coordinator/POSITIONS.md"
H = "explorations/coordinator/POSITIONS-history.md"
BASES = ["e5414f5bf", "892687076^"]

def show(rev, path):
    return subprocess.run(["git", "-C", REPO, "show", f"{rev}:{path}"],
                          capture_output=True, text=True, check=True).stdout

def current(path):
    if REV is None:
        return open(f"{REPO}/{path}", encoding="utf-8").read()
    return show(REV, path)

def entries(text):
    """(section heading, entry text) for every top-level bullet."""
    out, cur, section = [], None, None
    for line in text.split("\n"):
        if line.startswith("- "):
            if cur: out.append((section, "\n".join(cur)))
            cur = [line]
        elif cur and line[:1] in (" ", "\t") and line.strip():
            cur.append(line)
        else:
            if cur: out.append((section, "\n".join(cur)))
            cur = None
            if line.startswith("## "): section = line[3:]
    if cur: out.append((section, "\n".join(cur)))
    return out

pos = collections.Counter(e for _, e in entries(current(P)))
his = collections.Counter(e for _, e in entries(current(H)))

seen, bad = {}, 0
for rev in BASES:
    for sec, e in entries(show(rev, P)):
        seen.setdefault(e, (rev, sec))
counts = collections.Counter()
for e, (rev, sec) in seen.items():
    inP, inH = pos[e], his[e]
    where = ("POSITIONS" if inP else "") + ("+" if inP and inH else "") + ("history" if inH else "")
    if (inP > 0) + (inH > 0) != 1 or inP > 1 or inH > 1:
        bad += 1
        print(f"FAIL [{where or 'neither'}] {rev} / {sec}: {e[:110]!r}")
    counts[where or "neither"] += 1
print(f"baseline entries (distinct across {', '.join(BASES)}): {len(seen)}")
for k in ("POSITIONS", "history", "POSITIONS+history", "neither"):
    print(f"  {k}: {counts[k]}")
print("OK: every baseline entry verbatim in exactly one file" if not bad else f"FAILURES: {bad}")
sys.exit(1 if bad else 0)
EOF
